import{_ as p,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"ajaxHandler() - October CMS - 3.x","titleTemplate":false,"description":"Twig 函数","frontmatter":{"subtitle":"Twig 函数"},"headers":[{"level":2,"title":"访问数据","slug":"访问数据","link":"#访问数据","children":[]},{"level":2,"title":"使用响应","slug":"使用响应","link":"#使用响应","children":[]},{"level":2,"title":"处理错误","slug":"处理错误","link":"#处理错误","children":[]},{"level":2,"title":"处理重定向","slug":"处理重定向","link":"#处理重定向","children":[]},{"level":2,"title":"处理闪存消息","slug":"处理闪存消息","link":"#处理闪存消息","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/markup/function/ajax-handler.md","filePath":"3.x/zh-cn/markup/function/ajax-handler.md"}'),u={name:"3.x/zh-cn/markup/function/ajax-handler.md"};function r(d,n,k,g,h,w){const t=s("pre-heading"),e=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"ajaxHandler()",-1)),a(e),n[1]||(n[1]=i(`<p><code>ajaxHandler()</code> 函数在 Twig 中运行 AJAX 处理程序，并准备一个 <code>Cms\\Classes\\AjaxResponse</code> 响应对象。以下是调用 <strong>onResetPassword</strong> 处理程序的示例。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> result <span class="token operator">=</span> ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>返回的对象中可以包含以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>数据</th></tr></thead><tbody><tr><td><strong>data</strong></td><td>处理程序设置或返回的数据，也可通过直接调用对象获取。</td></tr><tr><td><strong>error</strong></td><td>处理程序执行期间抛出的错误。</td></tr><tr><td><strong>flash</strong></td><td>处理程序设置的闪存消息。</td></tr><tr><td><strong>redirect</strong></td><td>处理程序返回的重定向。</td></tr></tbody></table></div><h2 id="访问数据"><a href="#访问数据" class="header-anchor">#</a> 访问数据</h2><p>分配给页面的变量可在返回的对象中使用。以下是一个 AJAX 处理程序的定义示例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onResetPassword</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;someVariable&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;someValue&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>以下是调用 <strong>onResetPassword</strong> 处理程序的示例。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> result <span class="token operator">=</span> ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>处理程序返回的或在处理程序调用期间设置的 <strong>data</strong> 变量可通过返回的变量访问。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result<span class="token punctuation">.</span>someVariable <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="使用响应"><a href="#使用响应" class="header-anchor">#</a> 使用响应</h2><p>当<a href="./../../cms/resources/building-apis.html">在主题中构建 API</a> 时，可以将响应直接传递给 <code>response()</code> <a href="./response.html">Twig 函数</a>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>作为响应返回时，数据将以 JSON 格式在 <strong>data</strong> 属性中提供。</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>出于安全原因，页面变量不会包含在响应中。调用 <code>withPageVars</code> 方法可将它们包含在响应中。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>withPageVars<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><code>withVars</code> 方法可用于在响应中包含附加数据。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>withVars<span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token string"><span class="token punctuation">&#39;</span>token<span class="token punctuation">&#39;</span></span><span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>foobar<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="处理错误"><a href="#处理错误" class="header-anchor">#</a> 处理错误</h2><p>如果在处理程序执行期间发生异常，错误消息将在 <strong>error.message</strong> 属性中提供。如果错误是 <code>ValidationException</code>，则无效字段可在 <strong>error.fields</strong> 属性中找到。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> result<span class="token punctuation">.</span>error <span class="token delimiter punctuation">%}</span></span>
    An error occurred: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result<span class="token punctuation">.</span>error<span class="token punctuation">.</span>message <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>如果发生异常，错误信息将作为 <strong>error</strong> 属性提供。</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;error&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;An error occurred&quot;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>当从 AJAX 处理程序返回响应时，以下状态码用于对应的异常类型。</p><div class="table"><table tabindex="0"><thead><tr><th>异常</th><th>状态码</th></tr></thead><tbody><tr><td><code>ValidationException</code></td><td>422 Unprocessable Entity</td></tr><tr><td><code>ApplicationException</code></td><td>400 Bad Request</td></tr><tr><td><code>Exception</code></td><td>500 Internal Server Error</td></tr></tbody></table></div><h2 id="处理重定向"><a href="#处理重定向" class="header-anchor">#</a> 处理重定向</h2><p>如果 AJAX 处理程序触发了重定向，该重定向将在 <strong>redirect</strong> 属性中提供，并可直接返回。例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRedirect</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://octobercms.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>以下代码将作为响应重定向到浏览器。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onTest<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>该对象包含 <strong>redirect</strong> 消息以及数据。</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token property">&quot;redirect&quot;</span><span class="token operator">:</span> <span class="token string">&quot;https://octobercms.com&quot;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="处理闪存消息"><a href="#处理闪存消息" class="header-anchor">#</a> 处理闪存消息</h2><p>如果使用了闪存消息，它们将在 <strong>flash</strong> 属性中提供。以下处理程序为示例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onTest</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Test successful&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>调用处理程序并作为响应发送。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onTest<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>输出包含 <strong>flash</strong> 消息以及数据。</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token property">&quot;flash&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;success&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Test successful&quot;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../cms/resources/building-apis.html">构建 API 资源</a></li></ul></div>`,43))])}const x=p(u,[["render",r]]);export{v as __pageData,x as default};
